import java.util.*;
import java.io.*;

public class EdE {
    public static void main(String[] args) throws Exception {
        final int MOD = 998244353;
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long k = scanner.nextLong();

        long[] fact = new long[200001];
        fact[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        long totalSum = 0;
        for (int i = 0; i < n - k; i++) {
            long numerator = fact[(int)(n - k)];
            long invI = modInverse(fact[i], MOD);
            long invNMinusKMinusI = modInverse(fact[(int)(n - k - i)], MOD);
            long comb = (numerator * invI) % MOD;
            comb = (comb * invNMinusKMinusI) % MOD;
            long powerVal = power(n - k - i, n, MOD);
            if (i % 2 == 0) {
                totalSum = (totalSum + comb * powerVal) % MOD;
            } else {
                totalSum = (totalSum - comb * powerVal + MOD) % MOD;
            }
        }

        if (k >= n) {
            System.out.println(0);
        } else {
            if (k != 0) {
                totalSum = (totalSum * 2) % MOD;
            }
            totalSum = (totalSum * fact[(int) n]) % MOD;
            totalSum = (totalSum * modInverse(fact[(int) k], MOD)) % MOD;
            totalSum = (totalSum * modInverse(fact[(int)(n - k)], MOD)) % MOD;
            System.out.println(totalSum);
        }
        scanner.close();
    }

    public static long power(long base, long exp, int mod) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }

    public static long modInverse(long a, int m) {
        return power(a, m - 2, m);
    }
}
